def _wait(transport: Transport, attempt: int, r: Response | None) -> None:
    """Waits before attempt number `attempt` + 1 (attempt counts from 1)."""
    seconds: float = 2 ** (attempt - 1)
    if r is not None:
        for k, v in r.headers.items():
            if k.lower() == "retry-after":
                try:
                    seconds = int(str(v).strip())
                except ValueError:
